from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["dashboard-shell"])


@router.get("/dashboard", response_class=HTMLResponse, include_in_schema=False)
def dashboard_shell() -> str:
    return HTML


HTML = r'''<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AI F&O Intelligence</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,sans-serif;background:#080d19;color:#e8edf7;--p:#121a2c;--b:#26334d;--m:#8e9ab0;--g:#42d392;--r:#ff6f7d;--a:#f4c95d;--x:#71a7ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,#17243d,#080d19 45%);min-height:100vh}.wrap{max-width:1500px;margin:auto;padding:25px}.top{display:flex;justify-content:space-between;gap:15px;margin-bottom:16px}.title{font-size:30px;font-weight:800}.sub,.small{color:var(--m);font-size:12px}.nav{display:flex;gap:8px;margin-top:12px}.nav a{color:#b9c7df;text-decoration:none;border:1px solid var(--b);padding:7px 11px;border-radius:8px;background:#10182a;font-size:12px}.badge{border:1px solid var(--b);border-radius:999px;padding:9px 13px;background:#10182a;height:max-content}.notice{padding:13px 15px;border:1px solid #3a3040;border-radius:10px;background:#171c2d;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:14px}.card,.panel{background:rgba(18,26,44,.96);border:1px solid var(--b);border-radius:14px}.card{padding:15px}.label{color:var(--m);font-size:11px;text-transform:uppercase;letter-spacing:.08em}.value{font-size:24px;font-weight:800;margin-top:7px}.panel{overflow:hidden;margin-bottom:14px}.head{padding:15px 18px;border-bottom:1px solid var(--b);display:flex;justify-content:space-between;align-items:center}.body{padding:17px}.layout{display:grid;grid-template-columns:1fr 1fr;gap:14px}.flow{display:grid;grid-template-columns:1fr 1fr;gap:10px}.box{background:#0e1627;border:1px solid #22304a;border-radius:10px;padding:13px}.bar{height:9px;background:#202b40;border-radius:99px;overflow:hidden;margin-top:9px}.bar i{display:block;height:100%;background:var(--x)}table{width:100%;border-collapse:collapse;min-width:950px}th,td{padding:10px 12px;text-align:left;border-bottom:1px solid #202a40;font-size:12px;white-space:nowrap}th{color:var(--m);background:#0f1728}.table{overflow:auto}.bull{color:var(--g)}.bear{color:var(--r)}.amber{color:var(--a)}.empty{padding:32px;text-align:center;color:var(--m)}.health{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;padding:14px}.h{padding:11px;text-align:center;border:1px solid #22304a;border-radius:9px;background:#0e1627}.ok{color:var(--g)}.off{color:var(--r)}@media(max-width:1100px){.grid{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:1fr}}@media(max-width:700px){.wrap{padding:13px}.grid{grid-template-columns:repeat(2,1fr)}.health{grid-template-columns:repeat(2,1fr)}.top{display:block}.badge{margin-top:12px}}
</style></head><body><div class="wrap">
<div class="top"><div><div class="title">AI F&O Intelligence</div><div class="sub">Live flow during market hours • historical session replay after close • research only</div><div class="nav"><a href="/dashboard">Dashboard</a><a href="/strategy">SLO Strategy</a><a href="/price-action">Price Action</a></div></div><div id="badge" class="badge">Connecting…</div></div>
<div id="notice" class="notice">Connecting to dashboard data…</div>
<div class="grid"><div class="card"><div class="label">Data Mode</div><div id="mode" class="value">—</div><div id="modeSub" class="small">—</div></div><div class="card"><div class="label">Session</div><div id="session" class="value">—</div><div id="sessionSub" class="small">—</div></div><div class="card"><div class="label">Top SLO Score</div><div id="score" class="value">—</div><div id="scoreSub" class="small">—</div></div><div class="card"><div class="label">Opportunities</div><div id="count" class="value">—</div><div class="small">research candidates</div></div><div class="card"><div class="label">Feed Events</div><div id="events" class="value">—</div><div id="eventsSub" class="small">—</div></div></div>
<div class="layout"><div class="panel"><div class="head"><b>Session Regime</b><span id="regimeMeta" class="small"></span></div><div class="body"><div id="regime" class="value">WAITING</div><div id="regimeScore" class="small">—</div><div class="bar"><i id="regimeBar" style="width:0"></i></div></div></div><div class="panel"><div class="head"><b>CE vs PE Session Activity</b><span id="flowSource" class="small"></span></div><div class="body flow"><div class="box"><div class="label">Calls</div><div id="call" class="value bull">—</div><div id="callMeta" class="small"></div><div class="div bar"><i id="callBar"></i></div></div><div class="box"><div class="label">Puts</div><div id="put" class="value bear">—</div><div id="putMeta" class="small"></div><div class="bar"><i id="putBar" style="background:var(--r)"></i></div></div><div class="box"><div class="label">PCR OI</div><div id="pcrOi" class="value">—</div></div><div class="box"><div class="label">PCR Volume</div><div id="pcrVol" class="value">—</div></div></div></div></div>
<div class="panel"><div class="head"><b>🔥 Today's Research Opportunities</b><span id="method" class="small"></span></div><div class="table"><table><thead><tr><th>#</th><th>Underlying</th><th>Option</th><th>Direction</th><th>SLO</th><th>Premium</th><th>Stop</th><th>Target</th><th>DTE</th><th>Delta</th><th>Theta</th><th>IV</th><th>Volume</th><th>OI</th></tr></thead><tbody id="opp"></tbody></table></div></div>
<div class="panel"><div class="head"><b>Today's Active Underlyings</b><span class="small">Current session movement</span></div><div class="table"><table><thead><tr><th>#</th><th>Underlying</th><th>Direction</th><th>Score</th><th>Session %</th><th>Spot</th><th>High</th><th>Low</th></tr></thead><tbody id="under"></tbody></table></div></div>
<div class="panel"><div class="head"><b>Research System Health</b><span id="healthMeta" class="small"></span></div><div id="health" class="health"></div></div>
</div><script>
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=(v,d=2)=>v==null||v===''?'—':Number.isFinite(Number(v))?Number(v).toFixed(d):esc(v);
const pct=v=>v==null?'—':fmt(v,2)+'%';
const cls=v=>['BULLISH','UP','BUY_CALL'].includes(String(v).toUpperCase())?'bull':['BEARISH','DOWN','BUY_PUT'].includes(String(v).toUpperCase())?'bear':'';
async function refresh(){try{const r=await fetch('/dashboard/data',{cache:'no-store'});if(!r.ok)throw Error('dashboard/data HTTP '+r.status);const d=await r.json();const m=d.market||{},s=d.session||{},f=d.flow||{},reg=d.regime||{},sys=d.system||{},opp=d.opportunities||[],u=d.underlyings||[];document.getElementById('badge').innerHTML=`<span class="${m.state==='LIVE'?'ok':'amber'}">●</span> ${esc(m.label||m.state)} • ${new Date(m.now_ist).toLocaleTimeString('en-IN')}`;document.getElementById('notice').textContent=m.state==='LIVE'?'LIVE MARKET: reading the Groww feed and research pipeline.':'POST/PRE-MARKET: using the latest available session state.';document.getElementById('mode').textContent=String(d.source_mode||'—').replaceAll('_',' ');document.getElementById('modeSub').textContent=s.completed_at?'Historical session ready':'Live scanner state';document.getElementById('session').textContent=m.label||'—';document.getElementById('sessionSub').textContent=`${m.regular_open||'09:15'}–${m.regular_close||'15:40'} IST`;document.getElementById('score').textContent=opp.length?fmt(Math.max(...opp.map(x=>Number(x.score)||0))):'—';document.getElementById('scoreSub').textContent=opp.length?'best current research score':'no candidates yet';document.getElementById('count').textContent=opp.length;document.getElementById('events').textContent=fmt(sys.feed_events,0);document.getElementById('eventsSub').textContent=`${fmt(sys.feed_contracts,0)} contracts`;document.getElementById('regime').textContent=reg.state||'WAITING';document.getElementById('regimeScore').textContent=`signed ${fmt(reg.signed_score)} • confidence ${fmt(reg.confidence)}`;document.getElementById('regimeBar').style.width=Math.min(100,Math.abs(Number(reg.signed_score)||0))+'%';document.getElementById('regimeMeta').textContent=`B ${reg.bullish||0} / S ${reg.bearish||0} / N ${reg.neutral||0}`;document.getElementById('flowSource').textContent=f.source||'';document.getElementById('call').textContent=pct(f.call_activity_pct);document.getElementById('put').textContent=pct(f.put_activity_pct);document.getElementById('callMeta').textContent=`OI ${fmt(f.call_oi,0)} • Vol ${fmt(f.call_volume,0)}`;document.getElementById('putMeta').textContent=`OI ${fmt(f.put_oi,0)} • Vol ${fmt(f.put_volume,0)}`;document.getElementById('callBar').style.width=(f.call_activity_pct||0)+'%';document.getElementById('putBar').style.width=(f.put_activity_pct||0)+'%';document.getElementById('pcrOi').textContent=fmt(f.pcr_oi,3);document.getElementById('pcrVol').textContent=fmt(f.pcr_volume,3);document.getElementById('method').textContent=d.strategy?.method||'';document.getElementById('opp').innerHTML=opp.length?opp.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.underlying)}</td><td>${esc(x.option_symbol||x.symbol)}</td><td class="${cls(x.direction)}">${esc(x.direction)}</td><td class="score">${fmt(x.score)}</td><td>${fmt(x.premium)}</td><td>${fmt(x.stop_premium)}</td><td>${fmt(x.target_premium)}</td><td>${fmt(x.dte,0)}</td><td>${fmt(x.delta,3)}</td><td>${fmt(x.theta,4)}</td><td>${fmt(x.iv,2)}</td><td>${fmt(x.volume,0)}</td><td>${fmt(x.open_interest,0)}</td></tr>`).join(''):'<tr><td colspan="14" class="empty">No research opportunity yet. The scanner may still be warming up.</td></tr>';document.getElementById('under').innerHTML=u.length?u.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.underlying)}</td><td class="${cls(x.direction)}">${esc(x.direction)}</td><td class="score">${fmt(x.activity_score)}</td><td>${pct(x.session_change_pct||x.price_change_pct)}</td><td>${fmt(x.spot)}</td><td>${fmt(x.high)}</td><td>${fmt(x.low)}</td></tr>`).join(''):'<tr><td colspan="8" class="empty">No underlying ranking available yet.</td></tr>';const checks=[['Scanner',!!sys.scanner_running],['Ranking',!!sys.ranking_ready],['Feed events',Number(sys.feed_events||0)>0],['Historical',!!sys.historical_running||!!s.completed_at],['Trading',false],['API',true]];document.getElementById('health').innerHTML=checks.map(x=>`<div class="h"><div class="stageDot ${x[1]?'ok':'off'}">●</div>${x[0]}<div class="small">${x[1]?'READY':'WAITING'}</div></div>`).join('');document.getElementById('healthMeta').textContent=`updated ${new Date().toLocaleTimeString('en-IN')}`}catch(e){document.getElementById('badge').innerHTML='<span class="off">● API ERROR</span>';document.getElementById('notice').textContent='Dashboard UI error: '+e.message;console.error(e)}}
refresh();setInterval(refresh,10000);
</script></body></html>'''
